#!/usr/bin/env python3
"""Build a synthetic v2 Alpine .apk (concatenated gzip streams):

    [ .SIGN.RSA.<key> signature tar ][ .PKGINFO + scripts tar ][ data tar ]

so the C++ parser can be tested without a real apk-tools 2.x package.
"""
import gzip
import io
import os
import sys
import tarfile

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "synthetic_v2.apk")

PKGINFO = """\
# Generated by make_v2.py
pkgname = testpkg
pkgver = 2.3.4-r1
pkgdesc = A synthetic test package for the alpine reader.
url = https://example.org/testpkg
builddate = 1700000000
packager = Test Packager <packager@example.org>
maintainer = Test Maintainer <maint@example.org>
size = 4096
arch = x86_64
origin = testpkg
commit = 0123456789abcdef0123456789abcdef01234567
license = MIT
depend = musl>=1.2.4-r0
depend = so:libc.musl-x86_64.so.1
depend = !conflicting-pkg
depend = fuzzy-pkg~=1.2.3
provides = test-any=2.3.4-r1
replaces = oldtestpkg<1.0
install_if = base-files
recommends = suggest-pkg
provider_priority = 7
triggers = /usr/share/testdir
replaces_priority = 3
datahash = 0123456789abcdef0123456789abcdef
"""

POST_INSTALL = "#!/bin/sh\necho post-install ran \"$1\"\nexit 0\n"
PRE_INSTALL = "#!/bin/sh\necho pre-install\n"
TRIGGER = "#!/bin/sh\necho trigger \"$@\"\n"


def tar_bytes(entries):
    """entries: list of (name, data|None, type, mode, linkname)"""
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w", format=tarfile.USTAR_FORMAT) as tf:
        for name, data, typ, mode, linkname in entries:
            ti = tarfile.TarInfo(name)
            ti.mtime = 1700000123
            ti.mode = mode
            ti.type = typ
            ti.uname = "root"
            ti.gname = "root"
            if typ == tarfile.SYMTYPE:
                ti.linkname = linkname
                ti.size = 0
                tf.addfile(ti)
            elif typ == tarfile.DIRTYPE:
                ti.size = 0
                tf.addfile(ti)
            else:
                raw = data.encode() if isinstance(data, str) else data
                ti.size = len(raw)
                tf.addfile(ti, io.BytesIO(raw))
    return buf.getvalue()


def gz(raw):
    return gzip.compress(raw, 9, mtime=0)


def main():
    sig = tar_bytes([(".SIGN.RSA.test@example.org", b"\x00" * 512, tarfile.REGTYPE, 0o644, None)])
    control = tar_bytes([
        (".PKGINFO", PKGINFO, tarfile.REGTYPE, 0o644, None),
        (".pre-install", PRE_INSTALL, tarfile.REGTYPE, 0o755, None),
        (".post-install", POST_INSTALL, tarfile.REGTYPE, 0o755, None),
        (".trigger", TRIGGER, tarfile.REGTYPE, 0o755, None),
    ])
    data = tar_bytes([
        ("usr/", None, tarfile.DIRTYPE, 0o755, None),
        ("usr/bin/", None, tarfile.DIRTYPE, 0o755, None),
        ("usr/bin/testpkg", b"#!/bin/sh\necho hello\n", tarfile.REGTYPE, 0o755, None),
        ("etc/", None, tarfile.DIRTYPE, 0o755, None),
        ("etc/testpkg.conf", b"key = value\n", tarfile.REGTYPE, 0o644, None),
        ("usr/bin/testlink", None, tarfile.SYMTYPE, 0o777, "testpkg"),
    ])
    blob = gz(sig) + gz(control) + gz(data)
    with open(OUT, "wb") as f:
        f.write(blob)
    print("wrote %s (%d bytes)" % (OUT, len(blob)))
    print("  sig stream %d, control stream %d, data stream %d" %
          (len(gz(sig)), len(gz(control)), len(gz(data))))

    # variant without the leading signature stream (apk-tools allows that too)
    out2 = os.path.join(os.path.dirname(OUT), "synthetic_v2_nosig.apk")
    blob2 = gz(control) + gz(data)
    with open(out2, "wb") as f:
        f.write(blob2)
    print("wrote %s (%d bytes)" % (out2, len(blob2)))


if __name__ == "__main__":
    sys.exit(main())
